theorem thm_GAR (n : ℕ) : 
  let coin_denominations := [3*n - 2, 6*n - 1, 6*n + 2, 6*n + 5]
  let is_representable (k : ℕ) := ∃ (a b c d : ℕ), 
    k = a * (3*n - 2) + b * (6*n - 1) + c * (6*n + 2) + d * (6*n + 5)
  let smallest_non_representable := Nat.find (fun k => k > 0 ∧ ¬is_representable k)
  smallest_non_representable ≥ 17*n - 5 := by

theorem thm_GAR (a b : ℝ) (ha : 0 < a) (hab : a < b) (hb : b < 1) :
  let f : ℝ → ℝ := fun x => if x < 1/2 then x + 1/2 else x^2
  let g : ℕ → ℕ := fun n => n / (2^(Nat.factorization n 2))
  let S : ℕ → ℕ := fun n => ∑ k in Finset.range (2^n), g (k + 1)
  let a_seq : ℕ → ℝ := Nat.rec a (fun _ prev => f prev)
  let b_seq : ℕ → ℝ := Nat.rec b (fun _ prev => f prev)
  (∀ n : ℕ, n > 0 → (a_seq n - a_seq (n-1)) * (b_seq n - b_seq (n-1)) < 0) ∧
  (∀ n : ℕ, S n = (4^n + 2^n) / 3) := by

theorem thm_GAR (a : ℝ) (ha : a > 0) :
  let f : ℝ → ℝ := fun x => (Real.cot x + x) / (1 - x * Real.cot x)
  let A := {x : ℝ | x^2 + x - 6 > 0}
  let B := {x : ℝ | x^2 - 2*a*x + 3 ≤ 0}
  (∃ n m : ℤ, n ≠ m ∧ (n : ℝ) ∈ A ∩ B ∧ (m : ℝ) ∈ A ∩ B ∧ 
   ∀ k : ℤ, k ≠ n ∧ k ≠ m → (k : ℝ) ∉ A ∩ B) →
  ∀ x ∈ A ∩ B, deriv f x > 0 := by

theorem thm_GAR : 
  let f : ℝ → ℝ := fun x => x / (x^2 + 1)
  let g : ℝ → ℝ := deriv f
  let h : ℕ → ℝ := fun N => g (-2)
  let is_six_union_number (n : ℕ) : Prop := 
    (Finset.filter (fun k => k ∣ n) (Finset.range 9)).card ≥ 6
  ∃ N : ℕ, N > 2000 ∧ 
    is_six_union_number (Int.natAbs ⌊h N⌋) ∧
    (∀ M : ℕ, M > 2000 ∧ M < N → ¬is_six_union_number (Int.natAbs ⌊h M⌋)) := by
